from datetime import datetime, timedelta
from airflow.sdk import dag, task   # Airflow 3 import path; airflow.decorators is deprecated (as of 2026-10)

@dag(schedule="@daily", start_date=datetime(2025, 1, 1), catchup=False,
     default_args={"retries": 2, "retry_delay": timedelta(minutes=5)})
def train_daily():
    @task
    def build_features(data_interval_start=None) -> str:
        # write to a partition keyed by the interval, overwrite on rerun
        return f"features/dt={data_interval_start:%Y-%m-%d}/"

    @task
    def train(path: str) -> str:
        print("training on", path)
        return "model-version-ref"

    train(build_features())

train_daily()
